import{_ as n,a as r,b as t}from"./chunks/ai-create-03.Cig2rYP0.js";import{_ as i,o as a,c as l,a3 as s}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"Mit KI erstellen","description":"MiniTavern erzeugt aus einer Beschreibung und einem optionalen Referenzbild eine Charakterkarte. Felder prüfen, behalten, dann erstellen.","frontmatter":{"title":"Mit KI erstellen","description":"MiniTavern erzeugt aus einer Beschreibung und einem optionalen Referenzbild eine Charakterkarte. Felder prüfen, behalten, dann erstellen.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Mit KI erstellen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern erzeugt aus einer Beschreibung und einem optionalen Referenzbild eine Charakterkarte. Felder prüfen, behalten, dann erstellen."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/manual/ai-create"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/manual/ai-create"}]]},"headers":[],"relativePath":"de/manual/ai-create.md","filePath":"de/manual/ai-create.md","lastUpdated":1791861929000}'),d={name:"de/manual/ai-create.md"};function o(h,e,u,g,c,b){return a(),l("div",null,[...e[0]||(e[0]=[s('<h1 id="mit-ki-erstellen" tabindex="-1">Mit KI erstellen <a class="header-anchor" href="#mit-ki-erstellen" aria-label="Permalink to &quot;Mit KI erstellen&quot;">​</a></h1><p>Pfad: unten <strong>Charakterkarten</strong> → <strong>Erstellen / Importieren</strong> → <strong>Mit KI erstellen</strong>.</p><p>Zuerst eine <a href="./model-link">Modellverbindung</a> einrichten und den Test bestehen. Ohne nutzbares Modell bleibt Erzeugen gesperrt, die Seite verweist auf die Einrichtung.</p><h2 id="schritte" tabindex="-1">Schritte <a class="header-anchor" href="#schritte" aria-label="Permalink to &quot;Schritte&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+n+'" alt="Einstieg Mit KI erstellen"><figcaption>1 · Erstellen / Importieren → Mit KI erstellen</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="Beschreibung und Referenzbild"><figcaption>2 · Modell wählen, Beschreibung schreiben</figcaption></figure><figure class="shot-step"><img src="'+t+'" alt="Prüfen und Charakter erstellen"><figcaption>3 · Prüfen, dann erstellen</figcaption></figure></div><h2 id="erzeugen" tabindex="-1">Erzeugen <a class="header-anchor" href="#erzeugen" aria-label="Permalink to &quot;Erzeugen&quot;">​</a></h2><ol><li><strong>Modell</strong>: eine bereits eingerichtete Modellverbindung wählen. Die Standardverbindung ist vorausgewählt; eine andere ist möglich.</li><li><strong>Beschreibung</strong> (Pflicht): den gewünschten Charakter in einem Text beschreiben.</li><li><strong>Referenzbild</strong> (optional): tippen vergrößert das Bild; das Schließen-Symbol oben rechts entfernt es. Mit Bild muss das gewählte Modell Bilder unterstützen. Sonst Modell wechseln oder Bild entfernen.</li><li><strong>Erzeugen</strong> tippen. Die Schaltfläche zeigt «Wird erzeugt». Modell, Beschreibung und Referenzbild lassen sich währenddessen nicht ändern.</li></ol><p>Das Referenzbild zeigt dem Modell die Figur. Nach der ersten erfolgreichen Erzeugung wird es als <strong>Charakterbild</strong> übernommen. Das Modell zeichnet kein neues Bild. Ohne Referenzbild muss in der Prüfung selbst ein Bild gewählt werden, bevor die Karte erstellt werden kann.</p><p>Schlägt die Erzeugung fehl, erscheint ein Hinweis. <strong>Details ansehen</strong> zeigt den Grund. Abbrechen zeigt keine Fehlermeldung.</p><h2 id="prufung-und-behalten" tabindex="-1">Prüfung und Behalten <a class="header-anchor" href="#prufung-und-behalten" aria-label="Permalink to &quot;Prüfung und Behalten&quot;">​</a></h2><p>Nach Erfolg öffnet sich <strong>Charakter prüfen</strong>. Die Erzeugungsseite selbst zeigt keine Kartendaten.</p><ul><li>Name, Beschreibung, Tags, Persönlichkeit, Opening, Weltbuch und weitere Felder lassen sich direkt ändern.</li><li>Neben jedem KI-Feld und am ganzen <strong>Weltbuch</strong> gibt es <strong>Behalten</strong>. Ist es an, überschreibt die nächste Erzeugung diesen Eintrag nicht. Text ändern schaltet Behalten nicht von selbst ein.</li><li><strong>Neu erzeugen</strong> öffnet zuerst ein Eingabefeld. Aufschreiben, was sich ändern soll; leer lassen erzeugt erneut aus der ursprünglichen Beschreibung. Felder und das Weltbuch mit aktivem Behalten bleiben. Ist alles behalten, geht keine Anfrage raus.</li><li>Während der Erzeugung zeigt <strong>Neu erzeugen</strong> einen Ladezustand, <strong>Charakter erstellen</strong> wird zu Abbrechen.</li><li><strong>Charakter erstellen</strong> zeigt einen Ladehinweis, danach die Erfolgsmeldung. Bild, Name und Beschreibung sind Pflicht.</li><li>Figuren aus Anime, Film oder anderen bestehenden Werken können ein Weltbuch mitbringen. Nach dem Erstellen bleibt diese Einstellung auf der Karte und wird in ein Weltbuch kopiert, das Chats nutzen können. Siehe <a href="./lorebook">Weltbuch</a>.</li><li>Die Prüfung ohne Erstellen verlassen verwirft den Entwurf und kehrt zur Erzeugungsseite zurück. Das Referenzbild bleibt dort.</li></ul><h2 id="siehe-auch" tabindex="-1">Siehe auch <a class="header-anchor" href="#siehe-auch" aria-label="Permalink to &quot;Siehe auch&quot;">​</a></h2><ul><li><a href="./chara-card">Charakterkarten</a>: Import, Bearbeiten, Chatstart</li><li><a href="./model-link">Modellverbindung</a>: das Modell für die Erzeugung einrichten</li></ul>',14)])])}const k=i(d,[["render",o]]);export{p as __pageData,k as default};
